type PaneResizeDividerProps = {
  direction: PaneDirection;
  ratio: number;
  onRatioChange: (ratio: number) => void;
  ariaLabel?: string;
};

function PaneResizeDivider({ direction, ratio, onRatioChange, ariaLabel = "Resize terminal panes" }: PaneResizeDividerProps) {
  const dividerRef = useRef<HTMLDivElement>(null);
  const cleanupRef = useRef<(() => void) | null>(null);
  const isHorizontal = direction === "horizontal";

  useEffect(() => {
    return () => {
      if (cleanupRef.current) {
        cleanupRef.current();
        cleanupRef.current = null;
      }
    };
  }, []);

  const handlePointerDown = (event: React.PointerEvent) => {
    event.preventDefault();
    const parent = dividerRef.current?.parentElement;
    if (!parent) return;
    if (cleanupRef.current) {
      cleanupRef.current();
      cleanupRef.current = null;
    }
    document.body.style.cursor = isHorizontal ? "col-resize" : "row-resize";
    const parentRect = parent.getBoundingClientRect();

    const handlePointerMove = (pointerEvent: PointerEvent) => {
      const totalSize = isHorizontal ? parentRect.width : parentRect.height;
      if (totalSize <= 0) return;
      if (totalSize <= MIN_PANE_SIZE_PX * 2) {
        onRatioChange(0.5);
        return;
      }
      const position = isHorizontal ? pointerEvent.clientX - parentRect.left : pointerEvent.clientY - parentRect.top;
      const minimumRatio = MIN_PANE_SIZE_PX / totalSize;
      const clampedRatio = Math.max(minimumRatio, Math.min(1 - minimumRatio, position / totalSize));
      onRatioChange(Number(clampedRatio.toFixed(4)));
    };

    const cleanup = () => {
      document.body.style.cursor = "";
      window.removeEventListener("pointermove", handlePointerMove);
      window.removeEventListener("pointerup", cleanup);
      window.removeEventListener("pointercancel", cleanup);
      cleanupRef.current = null;
    };

    cleanupRef.current = cleanup;
    window.addEventListener("pointermove", handlePointerMove);
    window.addEventListener("pointerup", cleanup);
    window.addEventListener("pointercancel", cleanup);
  };

  return (
    <div
      ref={dividerRef}
      role="separator"
      aria-label={ariaLabel}
      aria-orientation={isHorizontal ? "vertical" : "horizontal"}
      aria-valuenow={Math.round(ratio * 100)}
      data-divider-hit-target="true"
      onPointerDown={handlePointerDown}
      className={`no-drag relative z-20 shrink-0 touch-none bg-border/80 ${
        isHorizontal ? "w-px cursor-col-resize" : "h-px cursor-row-resize"
      }`}
    >
      <span
        data-divider-hit-area="true"
        className={`absolute z-10 ${
          isHorizontal ? "-inset-x-1 inset-y-0 cursor-col-resize" : "-inset-y-1 inset-x-0 cursor-row-resize"
        }`}
      />
    </div>
  );
}

import { ChevronDown, ChevronUp, Search, X } from "lucide-react";
import React, { useCallback, useEffect, useRef, useState } from "react";

import type { TerminalInstance } from "../lib/terminalHostManager";
import { IconButton } from "./ui/IconButton";

export type TerminalSearchOverlayProps = {
  instance?: TerminalInstance;
  onClose: () => void;
};

export function TerminalSearchOverlay({ instance, onClose }: TerminalSearchOverlayProps) {
  const [query, setQuery] = useState("");
  const [resultIndex, setResultIndex] = useState<number | null>(null);
  const [resultCount, setResultCount] = useState<number | null>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    inputRef.current?.focus();
    inputRef.current?.select();
  }, []);

  useEffect(() => {
    if (!instance?.searchAddon?.onDidChangeResults) return;
    const disposable = instance.searchAddon.onDidChangeResults((e) => {
      setResultIndex(e.resultIndex);
      setResultCount(e.resultCount);
    });
    return () => {
      disposable?.dispose?.();
    };
  }, [instance]);

  const handleFindNext = useCallback(() => {
    if (!query || !instance?.searchAddon) return;
    instance.searchAddon.findNext(query, { incremental: false });
  }, [instance, query]);

  const handleFindPrevious = useCallback(() => {
    if (!query || !instance?.searchAddon) return;
    instance.searchAddon.findPrevious(query, { incremental: false });
  }, [instance, query]);

  const handleQueryChange = (newQuery: string) => {
    setQuery(newQuery);
    if (!newQuery) {
      instance?.searchAddon?.clearDecorations();
      setResultIndex(null);
      setResultCount(null);
    } else {
      instance?.searchAddon?.findNext(newQuery, { incremental: true });
    }
  };

  const handleClose = useCallback(() => {
    instance?.searchAddon?.clearDecorations();
    onClose();
    instance?.terminal?.focus();
  }, [instance, onClose]);

  const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === "Enter") {
      e.preventDefault();
      e.stopPropagation();
      if (e.shiftKey) {
        handleFindPrevious();
      } else {
        handleFindNext();
      }
    } else if (e.key === "Escape") {
      e.preventDefault();
      e.stopPropagation();
      handleClose();
    }
  };

  return (
    <div
      role="search"
      aria-label="Terminal search"
      className="no-drag absolute top-2 right-4 z-40 flex items-center gap-1 rounded border border-border bg-card/95 p-1 text-foreground shadow-lg backdrop-blur-sm"
      onKeyDown={(e) => {
        if (e.key === "Escape") {
          e.stopPropagation();
          handleClose();
        }
      }}
    >
      <div className="relative flex items-center">
        <Search className="pointer-events-none absolute left-2 size-3 text-muted-foreground" />
        <input
          ref={inputRef}
          type="text"
          aria-label="Find in terminal"
          data-testid="terminal-search-input"
          placeholder="Find..."
          value={query}
          onChange={(e) => handleQueryChange(e.target.value)}
          onKeyDown={handleKeyDown}
          className="h-6 w-44 rounded border border-border bg-background pl-6 pr-2 text-xs text-foreground placeholder:text-muted-foreground/60 focus:border-primary focus:outline-none"
        />
      </div>
      {resultCount !== null && query.length > 0 ? (
        <span className="px-1 font-mono text-[10px] text-muted-foreground">
          {resultCount === 0 ? "0/0" : `${(resultIndex ?? 0) + 1}/${resultCount}`}
        </span>
      ) : null}
      <IconButton
        label="Previous match"
        aria-label="Previous match"
        size="sm"
        className="size-5 rounded p-0 text-muted-foreground hover:text-foreground"
        onClick={handleFindPrevious}
      >
        <ChevronUp className="size-3" />
      </IconButton>
      <IconButton
        label="Next match"
        aria-label="Next match"
        size="sm"
        className="size-5 rounded p-0 text-muted-foreground hover:text-foreground"
        onClick={handleFindNext}
      >
        <ChevronDown className="size-3" />
      </IconButton>
      <IconButton
        label="Close search"
        aria-label="Close search"
        size="sm"
        className="size-5 rounded p-0 text-muted-foreground hover:text-foreground"
        onClick={handleClose}
      >
        <X className="size-3" />
      </IconButton>
    </div>
  );
}

import { useEffect, useState } from "react";
